#!/bin/bash
# Builds /usr/lib/libevent.dylib: libevent 2.1.12-stable's core (CMake's
# SRC_CORE plus the select/poll/kqueue backends), as vendored by NetBSD in
# external/bsd/libevent/dist (NetBSD's few local edits use its __UNCONST,
# hence -include compat/netbt-user/netbt_user.h) of our fork anurodhp/netbsd-src
# (third_party/netbsd-src). NetBSD's bthcid uses it
# (docs/bluetooth-stack-plan.md S4).
#
# event-config.h is generated by libevent's own CMake configure, targeting
# the iPhoneOS SDK with the Xcode 12 clang (no build is run by CMake: it
# only answers the feature checks: kqueue, poll, select, arc4random, ...; no
# epoll/eventfd/pipe2/accept4). The sources are then compiled and linked
# here with this project's usual dylib recipe.
set -euo pipefail
cd "$(dirname "$0")"

OUT="libc_build"
T="../../third_party"
LE="$T/netbsd-src/external/bsd/libevent/dist"
XCODE12="/Applications/Xcode-12.app/Contents/Developer"
CLANG="$XCODE12/Toolchains/XcodeDefault.xctoolchain/usr/bin/clang"
SDK="$XCODE12/Platforms/iPhoneOS.platform/Developer/SDKs/iPhoneOS.sdk"
NEWLD_BINDIR="$(xcode-select -p)/Toolchains/XcodeDefault.xctoolchain/usr/bin"
S="$OUT/system"

[ -f "$LE/event.c" ] || { echo "error: $LE not found -- run ./setup_third_party.sh" >&2; exit 1; }
command -v cmake >/dev/null || { echo "error: cmake is needed to generate event-config.h" >&2; exit 1; }
for f in libsystem_kernel libsystem_c libsystem_malloc libsystem_platform libsystem_pthread libdyld libSystem.B libresolv libinfo; do
    [ -f "$S/$f.dylib" ] || { echo "error: $S/$f.dylib not found -- build it first" >&2; exit 1; }
done

CFG="$PWD/$OUT/libevent_cmake"
rm -rf "$CFG"
mkdir -p "$CFG"
(cd "$CFG" && cmake "$OLDPWD/$LE" -DCMAKE_POLICY_VERSION_MINIMUM=3.5 \
    -DCMAKE_SYSTEM_NAME=iOS -DCMAKE_OSX_SYSROOT="$SDK" -DCMAKE_OSX_ARCHITECTURES=arm64 \
    -DCMAKE_OSX_DEPLOYMENT_TARGET=14.4 -DCMAKE_C_COMPILER="$CLANG" \
    -DEVENT__DISABLE_OPENSSL=ON -DEVENT__DISABLE_MBEDTLS=ON -DEVENT__DISABLE_TESTS=ON \
    -DEVENT__DISABLE_SAMPLES=ON -DEVENT__DISABLE_BENCHMARK=ON -DEVENT__DISABLE_REGRESS=ON \
    -DEVENT__LIBRARY_TYPE=STATIC > cmake.log 2>&1) \
    || { tail -20 "$CFG/cmake.log" >&2; echo "error: libevent cmake configure failed" >&2; exit 1; }
[ -f "$CFG/include/event2/event-config.h" ] || { echo "error: no generated event-config.h" >&2; exit 1; }

# Headers for consumers: libevent's public include/ plus the generated one.
INC="$OUT/libevent_include"
rm -rf "$INC"
mkdir -p "$INC"
cp -R "$LE/include/." "$INC/"
cp "$CFG/include/event2/event-config.h" "$INC/event2/"

OBJ="$OUT/libevent_obj"
rm -rf "$OBJ"
mkdir -p "$OBJ"
CFLAGS=(-isysroot "$SDK" -target arm64-apple-ios14.4 -c -O1 -Wno-nullability-completeness
    -D_FORTIFY_SOURCE=0 -DHAVE_CONFIG_H -Werror=implicit-function-declaration
    -include ../../compat/netbt-user/netbt_user.h
    -I "$CFG/include" -I "$LE/include" -I "$LE" -I "$LE/compat")
for s in buffer bufferevent bufferevent_filter bufferevent_pair bufferevent_ratelim bufferevent_sock \
         event evmap evthread evutil evutil_rand evutil_time listener log signal strlcpy \
         select poll kqueue evthread_pthread; do
    "$CLANG" "${CFLAGS[@]}" "$LE/$s.c" -o "$OBJ/$s.o"
done

D="$S/libevent.dylib"
rm -f "$D"
"$CLANG" -isysroot "$SDK" -target arm64-apple-ios14.4 -dynamiclib -nostdlib \
    -install_name /usr/lib/libevent.dylib \
    -Wl,-not_for_dyld_shared_cache -B"$NEWLD_BINDIR" -Wl,-fixup_chains \
    -o "$D" "$OBJ"/*.o \
    "$S/libinfo.dylib" "$S/libresolv.dylib" "$S/libsystem_c.dylib" "$S/libsystem_malloc.dylib" \
    "$S/libsystem_kernel.dylib" "$S/libsystem_platform.dylib" "$S/libsystem_pthread.dylib" \
    "$S/libdyld.dylib" "$S/libSystem.B.dylib"
otool -hv "$D" | grep -q " DYLIB " || { echo "error: $D is not a dylib" >&2; exit 1; }
./bind_target_audit.sh "$D" || { echo "error: $D has an unresolvable two-level bind" >&2; exit 1; }
codesign -s - -f "$D" 2>&1 | grep -v "replacing existing signature" || true
echo "wrote $D"
